const fs=require('fs'),path=require('path'),vm=require('vm'),assert=require('assert/strict');
const root=path.join(__dirname,process.argv.includes('--tree')?'skill-tree-20261006':'combat-spectacle-20261006'),api=require(path.join(root,'spell-spectacle.js'));
const expected=[['ultima','光','ultima'],['ultima','闇','void'],['magma','火','magma'],['rift','水','rift'],['nova','風','storm'],['rain','光','rain'],['ninpo','風','phantom']];
for(const [fx,el,kind]of expected)assert.equal(api.describe({}, {fx,el}).kind,kind);
assert.equal(api.describe({boss:true},{kind:'phys',nm:'爪擊'}).kind,'claw');assert.equal(api.describe({boss:true},{nm:'鎖鏈鞭'}).kind,'chain');
let depth=0,calls=0;const gradient={addColorStop(t,c){assert.ok(t>=0&&t<=1);assert.equal(typeof c,'string')}};
const ctx=new Proxy({}, {get(o,k){if(k==='save')return()=>depth++;if(k==='restore')return()=>{depth--;assert.ok(depth>=0)};if(k==='createLinearGradient'||k==='createRadialGradient')return(...args)=>{assert.ok(args.every(Number.isFinite));return gradient};return(...args)=>{calls++;for(const a of args)if(typeof a==='number')assert.ok(Number.isFinite(a),'non-finite '+k)}},set(o,k,v){if(typeof v==='number')assert.ok(Number.isFinite(v));o[k]=v;return true}});
for(const kind of ['cast','ultima','magma','rift','wind','storm','earth','void','rain','chain','claw','rend','phantom','beam'])for(const t of [0,.12,.35,.65,.9,1])api.draw(ctx,{kind,x:190,y:410,foot:510,r:115,c:'#fff2bb',edge:'#e7bd59',boss:true,from:{x:65,y:445}},t);
assert.equal(depth,0);const js=fs.readFileSync(path.join(root,'duel-cinema.js'),'utf8');new vm.Script(js);assert.ok(js.includes('96-particles.length'));assert.ok(js.includes('fields.length<8'));assert.ok(js.includes('Math.min(4,1/Math.max(.25,getSpeed()))'));
console.log(JSON.stringify({passed:'14 signature renderers at 6 phases, balanced canvas state, finite geometry, boss classifiers, particle/field caps and speed sync',drawCalls:calls}));
